package practice;

import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Modifier;
import java.lang.reflect.RecordComponent;
import java.util.Map;

/** Turns one imported row (column name to value) into an object of the requested type. */
public final class RowMapper {

    private RowMapper() {
    }

    /** Builds an object of {@code type} from one row of the import. */
    public static <T> T map(Class<T> type, Map<String, ?> row) {
        try {
            return type.isRecord() ? toRecord(type, row) : toBean(type, row);
        } catch (ReflectiveOperationException e) {
            throw new IllegalStateException("cannot map a row to " + type.getName(), e);
        }
    }

    /** Beans: the no-arg constructor, then every instance field set from the column of its name. */
    static <T> T toBean(Class<T> type, Map<String, ?> row) throws ReflectiveOperationException {
        Constructor<T> noArg = type.getDeclaredConstructor();
        noArg.setAccessible(true);
        T bean = noArg.newInstance();
        for (Field field : type.getDeclaredFields()) {
            if (Modifier.isStatic(field.getModifiers())) {
                continue;
            }
            field.setAccessible(true);
            field.set(bean, row.get(field.getName()));
        }
        return bean;
    }

    /**
     * Records: TODO. Build a record of {@code type} from the row. Every check the record makes on
     * its values must still run on imported rows.
     */
    static <T> T toRecord(Class<T> type, Map<String, ?> row) throws ReflectiveOperationException {
        RecordComponent[] components = type.getRecordComponents();
        Class<?>[] types = new Class<?>[components.length];
        Object[] values = new Object[components.length];
        for (int i = 0; i < components.length; i++) {
            types[i] = components[i].getType();
            values[i] = row.get(components[i].getName());
        }
        Constructor<T> canonical = type.getDeclaredConstructor(types);
        canonical.setAccessible(true);
        return canonical.newInstance(values);
    }
}

package practice;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.ConsoleHandler;
import java.util.logging.Level;
import java.util.logging.Logger;

/** Run executes this file. Change the calls in main and see what prints. Submit grades. */
public class TryIt {
    /** Held here, so the JDK's own exit notice stays off: a logger nothing holds can be dropped. */
    private static final Logger JDK_EXIT = Logger.getLogger("java.lang.Runtime");

    public static void main(String[] args) {
        // Turn the logger up, so the log lines of your code show under the printed lines.
        System.setProperty("java.util.logging.SimpleFormatter.format", "%4$s %5$s%n");
        // Only this handler prints, and it leaves out the JDK's own detail.
        Logger root = Logger.getLogger("");
        for (java.util.logging.Handler before : root.getHandlers()) {
            root.removeHandler(before);
        }
        ConsoleHandler handler = new ConsoleHandler();
        handler.setLevel(Level.ALL);
        handler.setFilter(entry -> !String.valueOf(entry.getLoggerName()).matches("(java|javax|jdk|sun|com\\.sun)\\..*"));
        root.setLevel(Level.ALL);
        root.addHandler(handler);
        JDK_EXIT.setLevel(Level.OFF);

        // A stand-in for the collaborator, like the one the tests use for the first main case.
        try {
            Map<String, Object> meterRow = new LinkedHashMap<>();
            meterRow.put("kwh", 1_284.5);
            meterRow.put("_sourceLine", 77);
            meterRow.put("meterId", "MTR-310");
            meterRow.put("smart", true);
            System.out.println("meter: " + RowMapper.map(Meter.class, meterRow));
            Map<String, Object> palletRow = new LinkedHashMap<>();
            palletRow.put("warehouse", "Lille");
            palletRow.put("label", "PAL-66");
            palletRow.put("layers", 5);
            System.out.println("pallet: " + RowMapper.map(Pallet.class, palletRow));
            palletRow.put("layers", -1);
            try {
                RowMapper.map(Pallet.class, palletRow);
                System.out.println("pallet with -1 layers: mapped");
            } catch (RuntimeException refused) {
                Throwable reason = refused;
                while (reason.getCause() != null) {
                    reason = reason.getCause();
                }
                System.out.println("pallet with -1 layers: refused, " + reason.getMessage());
            }
        } catch (RuntimeException stopped) {
            // A method you have not finished, or a bug, stops here with its message, not a build error.
            System.out.println("Run stopped: " + stopped);
        }
    }

    record Meter(String meterId, double kwh, boolean smart) {
    }

    record Pallet(String label, int layers, String warehouse) {
        Pallet {
            if (layers < 1) {
                throw new IllegalArgumentException("layers must be at least 1, was " + layers);
            }
        }
    }
}

